import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"ADR-011: Static film grain by default","description":"","frontmatter":{},"headers":[],"relativePath":"adr/011-static-grain-by-default.md","filePath":"adr/011-static-grain-by-default.md"}'),r={name:"adr/011-static-grain-by-default.md"};function n(o,e,c,d,l,f){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-011-static-film-grain-by-default" tabindex="-1">ADR-011: Static film grain by default <a class="header-anchor" href="#adr-011-static-film-grain-by-default" aria-label="Permalink to &quot;ADR-011: Static film grain by default&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-15</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>FR-RT-5 asks for grain chosen from pre-generated tiles by frame index. Measured on a 6 s excerpt of <code>examples/season1/ep01</code> (master settings, CRF 18): no grain 1.9 Mb/s, grain refreshed every frame 64.5 Mb/s, every 6 frames 21.5 Mb/s, static 5.9 Mb/s. Per-frame noise is incompressible: it makes masters ~500 MB, slows every encode, and starves the size-capped share file of bits for the actual content. TikTok/Reels/Shorts re-encode uploads and remove fine grain anyway.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Grain is a seeded noise texture whose offset is chosen from 8 positions by frame index at the rate <code>theme.chrome.grain_fps</code>. The default is <code>0</code> (static texture). Series that want animated grain can set e.g. <code>grain_fps: 6</code> and accept the bitrate cost.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The look keeps its texture, renders stay deterministic, and share files spend their bits on text and diagrams.</p>',8)])])}const u=a(r,[["render",n]]);export{m as __pageData,u as default};
